/* ICP correspondence: GPU KD-tree nearest-neighbour search and reduction. */
#include "solve.h"
#include "kdtree.h"
#include <cuda_runtime.h>
#include <cfloat>

static int*    g_match_idx = nullptr;
static double* g_centroid_acc = nullptr;
static double* g_H_acc = nullptr;
static double* g_err_acc = nullptr;
static int g_match_cap = 0;

/*
 * The tree is laid out in the same order as the host KDNode tree.  A small
 * explicit stack is considerably cheaper than either recursion (which is
 * not supported on all the devices this is built for) or a global worklist.
 * A balanced tree with 500K leaves has a maximum depth of 20.
 */
__global__ void kd_nn_kernel(const float* __restrict__ src,
                             const float* __restrict__ tgt,
                             const KDNode* __restrict__ nodes,
                             int N, float limit,
                             int* __restrict__ matches,
                             double* __restrict__ sums,
                             int* __restrict__ count) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= N) return;
    const float px = src[3*i], py = src[3*i+1], pz = src[3*i+2];

    float best = limit;
    int best_j = -1;
    int stack[64];
    int sp = 0;
    stack[sp++] = 0;
    while (sp) {
        int ni = stack[--sp];
        if (ni < 0) continue;
        const KDNode n = nodes[ni];
        float dx = fmaxf(0.0f, fmaxf(n.bbox_min[0]-px, px-n.bbox_max[0]));
        float dy = fmaxf(0.0f, fmaxf(n.bbox_min[1]-py, py-n.bbox_max[1]));
        float dz = fmaxf(0.0f, fmaxf(n.bbox_min[2]-pz, pz-n.bbox_max[2]));
        if (dx*dx + dy*dy + dz*dz >= best) continue;

        int j = n.point_idx;
        float qx = tgt[3*j], qy = tgt[3*j+1], qz = tgt[3*j+2];
        float ex=px-qx, ey=py-qy, ez=pz-qz;
        float d = ex*ex + ey*ey + ez*ez;
        if (d < best) { best=d; best_j=j; }

        if (n.axis != 3) {
            float v = (n.axis == 0) ? px : ((n.axis == 1) ? py : pz);
            float pivot = (n.axis == 0) ? qx : ((n.axis == 1) ? qy : qz);
            int near_node = (v < pivot) ? n.left : n.right;
            int far_node  = (v < pivot) ? n.right : n.left;
            /* LIFO: visit the near side first, just as the CPU reference. */
            if (far_node >= 0) stack[sp++] = far_node;
            if (near_node >= 0) stack[sp++] = near_node;
        }
    }

    if (best_j < 0) { matches[i] = -1; return; }
    matches[i] = best_j;
    atomicAdd(&sums[0], (double)px); atomicAdd(&sums[1], (double)py);
    atomicAdd(&sums[2], (double)pz);
    atomicAdd(&sums[3], (double)tgt[3*best_j]);
    atomicAdd(&sums[4], (double)tgt[3*best_j+1]);
    atomicAdd(&sums[5], (double)tgt[3*best_j+2]);
    atomicAdd(count, 1);
}

__global__ void accumulate_H_kernel(const float* __restrict__ src,
                                    const float* __restrict__ tgt,
                                    const int* __restrict__ match,
                                    int N, double cx, double cy, double cz,
                                    double qx0, double qy0, double qz0,
                                    double* __restrict__ H,
                                    double* __restrict__ err) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= N) return;
    int j=match[i]; if (j<0) return;
    double x=(double)src[3*i]-cx, y=(double)src[3*i+1]-cy, z=(double)src[3*i+2]-cz;
    double qx=(double)tgt[3*j]-qx0, qy=(double)tgt[3*j+1]-qy0, qz=(double)tgt[3*j+2]-qz0;
    atomicAdd(&H[0],x*qx); atomicAdd(&H[1],x*qy); atomicAdd(&H[2],x*qz);
    atomicAdd(&H[3],y*qx); atomicAdd(&H[4],y*qy); atomicAdd(&H[5],y*qz);
    atomicAdd(&H[6],z*qx); atomicAdd(&H[7],z*qy); atomicAdd(&H[8],z*qz);
    double dx=(double)src[3*i]-(double)tgt[3*j];
    double dy=(double)src[3*i+1]-(double)tgt[3*j+1];
    double dz=(double)src[3*i+2]-(double)tgt[3*j+2];
    atomicAdd(err,dx*dx+dy*dy+dz*dz);
}

__global__ void finalize_kernel(const double* H, const double* e,
                                float* Ho, float* eo) {
    int t=threadIdx.x; if(t<9) Ho[t]=(float)H[t]; if(t==9) *eo=(float)*e;
}

static void ensure_scratch(int N, cudaStream_t s) {
    if (N > g_match_cap) {
        if (g_match_idx) cudaFree(g_match_idx);
        cudaMalloc(&g_match_idx,(size_t)N*sizeof(int)); g_match_cap=N;
    }
    if(!g_centroid_acc) cudaMalloc(&g_centroid_acc,6*sizeof(double));
    if(!g_H_acc) cudaMalloc(&g_H_acc,9*sizeof(double));
    if(!g_err_acc) cudaMalloc(&g_err_acc,sizeof(double));
    cudaMemsetAsync(g_centroid_acc,0,6*sizeof(double),s);
    cudaMemsetAsync(g_H_acc,0,9*sizeof(double),s);
    cudaMemsetAsync(g_err_acc,0,sizeof(double),s);
}

void icp_correspondence(const float* src,const float* tgt,int N,int M,float d_max,
                        const void* kd_nodes,int n_nodes,float* H_out,float* err_out,
                        int* count_out,cudaStream_t stream) {
    (void)M; (void)n_nodes;
    ensure_scratch(N,stream);
    cudaMemsetAsync(count_out,0,sizeof(int),stream);
    int block=256, grid=(N+block-1)/block;
    kd_nn_kernel<<<grid,block,0,stream>>>(src,tgt,(const KDNode*)kd_nodes,N,
                                          d_max*d_max,g_match_idx,g_centroid_acc,count_out);

    double c[6]; int cnt;
    cudaMemcpyAsync(c,g_centroid_acc,sizeof(c),cudaMemcpyDeviceToHost,stream);
    cudaMemcpyAsync(&cnt,count_out,sizeof(cnt),cudaMemcpyDeviceToHost,stream);
    cudaStreamSynchronize(stream);
    double cx=0,cy=0,cz=0,qx=0,qy=0,qz=0;
    if(cnt){ double inv=1.0/cnt; cx=c[0]*inv;cy=c[1]*inv;cz=c[2]*inv;
             qx=c[3]*inv;qy=c[4]*inv;qz=c[5]*inv; }
    accumulate_H_kernel<<<grid,block,0,stream>>>(src,tgt,g_match_idx,N,cx,cy,cz,qx,qy,qz,g_H_acc,g_err_acc);
    finalize_kernel<<<1,32,0,stream>>>(g_H_acc,g_err_acc,H_out,err_out);
}
